import{_ as i,l as o,o as e,c as l,v as t,p as s,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"事件驱动全景","description":"","frontmatter":{"title":"事件驱动全景","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/event-driven-overview.md","filePath":"quant/event-driven-overview.md","lastUpdated":1789023840000}'),u={name:"quant/event-driven-overview.md"};function E(c,a,_,A,f,m){const n=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="事件驱动全景" tabindex="-1">事件驱动全景 <a class="header-anchor" href="#事件驱动全景" aria-label="Permalink to &quot;事件驱动全景&quot;">​</a></h1><div class="epigraph"><p>事件驱动吃的是公告后的不完备定价与交易摩擦，不是截面因子的慢溢价；每类事件有自己的失败模式。</p><footer>—— 并购套利见 Mitchell and Pulvino；对照事件研究法的识别，本课只做策略地图</footer></div><p><a href="/quant/one-thirty-thirty">上一课</a>把 130/30 写成带有限卖空的增强指数：净暴露约 100%，不是市场中性，评价用 TE 与超额。缺口是日历：多空与 130/30 仍是截面组合，并购、分拆、重组、破产的完成时点由公司事件驱动，不能收成同一个「事件因子」。本课给事件驱动地图：公告、完成不确定性、资金占用，按完成风险对漂移风险分桶。不重讲 30% 借券。具体一类见 <a href="/quant/event-study">事件研究</a> 与 <a href="/quant/merger-arbitrage">并购套利</a>；后课全球宏观默认事件簿的平静期夏普不能当容量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>130/30 仍按截面日历再平衡；并购与破产的完成日不是月末。<a href="/quant/pead-sue">PEAD</a> 是盈余公告后的漂移，偏系统、可做截面。并购套利是 deal 完成的二元风险，偏特异、相关在监管否决时会突然升。分拆、毒丸、指数事件（后课纳入）又不同。问题是资金与风险预算：事件簿的「夏普」在平静期高，在 2008 年并购破裂期一起爆。地图要按<strong>完成风险 vs 漂移风险</strong>分桶，而不是按彭博行业标签。</p><p>共同零件：公告日流动性空洞、借券、法律文件、完成日不确定。回测若用公告后收盘价当成交，会高估，见 <a href="/quant/event-study">事件研究</a> 的时间戳。</p><h3 id="不要用因子模型解释掉事件" tabindex="-1">不要用因子模型解释掉事件 <a class="header-anchor" href="#不要用因子模型解释掉事件" aria-label="Permalink to &quot;不要用因子模型解释掉事件&quot;">​</a></h3><p>事件收益对 HML/动量有暴露，但残差才是策略。强行行业中性可能对冲掉并购价差本身。风险模型应用于剩余，并对单笔 deal 设集中限额。</p><p><span class="marginnote">SPAC、PIPEs、困境债各有法律与流动性结构，不能从现金并购公式类推。地图只点名，细节留给专门产品课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分类：并购套利、分拆/配售、困境/破产、盈余漂移、监管/政策事件。每类写：催化剂、失败模式、对冲（行业、指数、期权）、容量。组合：低相关的事件之间分散，但承认体制相关（信贷紧缩）。执行：公告后冲击模型单独校准。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>事件把信息集中释放，市场在完成概率上交易。策略卖的是「概率被标错」或「有人要流动性」。因子策略卖的是长期风险补偿。时钟不同，拥挤模式也不同：并购套利的拥挤是 spread 过窄，因子拥挤是估值压缩。</p>',13)),(e(),s(p,null,{default:r(()=>[h(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Ann%5B%22%E5%85%AC%E5%91%8A%22%5D%20--%3E%20Drift%5B%22%E6%BC%82%E7%A7%BB%E7%B1%BB%20PEAD%22%5D%0A%20%20Ann%20--%3E%20Bin%5B%22%E5%AE%8C%E6%88%90%E7%B1%BB%20%E5%B9%B6%E8%B4%AD%22%5D%0A%20%20Drift%20--%3E%20Sys%5B%22%E5%8F%AF%E6%88%AA%E9%9D%A2%E5%8C%96%22%5D%0A%20%20Bin%20--%3E%20Idio%5B%22Deal%20%E9%A3%8E%E9%99%A9%E5%8A%A0%E4%BD%93%E5%88%B6%E7%9B%B8%E5%85%B3%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>内幕与重大非公开信息是法律边界，本课只处理公开公告后的交易。跨境并购的监管时钟更长。不要把未公告谣言当事件驱动回测。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>事件驱动按完成风险与漂移风险分桶，不是一个因子。</li><li>平静期夏普不可外推到破裂期的相关 1。</li><li>时间戳与冲击决定回测是否可交易。</li><li>出处：Mitchell and Pulvino, <em>Journal of Finance</em>, 2001（并购套利）；盈余漂移见 PEAD 课文献。</li></ul>',4))])}const q=i(u,[["render",E]]);export{B as __pageData,q as default};
